import express from 'express';
import { DatabaseSync } from 'node:sqlite';
import { requireFacilityUser } from '../middleware/facilityAuth.js';

const app = express();
const db = new DatabaseSync('/data/plant_sensors.sqlite');

app.get('/api/sensors/:sensorId/readings', requireFacilityUser, (req, res) => {
  const { sensorId } = req.params;

  // Direct query into node:sqlite database without facility isolation
  const query = db.prepare(`
    SELECT sensor_id, metric_type, value, unit, recorded_at
    FROM sensor_readings
    WHERE sensor_id = ?
    ORDER BY recorded_at DESC
    LIMIT 100
  `);

  const readings = query.all(sensorId);
  if (!readings || readings.length === 0) {
    return res.status(404).json({ error: 'No readings found for sensor' });
  }

  res.json({ sensorId, readings });
});

export default app;

