import express from 'express';
import { DatabaseSync } from 'node:sqlite';
import { requireFacilityUser } from '../middleware/facilityAuth.js';

const app = express();
const db = new DatabaseSync('/data/plant_sensors.sqlite');

app.get('/api/sensors/:sensorId/readings', requireFacilityUser, (req, res) => {
  const { sensorId } = req.params;

  // Verify that the sensor is registered to the user's authorized facility
  const checkSensor = db.prepare(`
    SELECT id FROM facility_sensors WHERE id = ? AND facility_id = ?
  `).get(sensorId, req.user.facilityId);

  if (!checkSensor) {
    return res.status(403).json({ error: 'Access denied: Sensor not registered to your facility' });
  }

  const query = db.prepare(`
    SELECT sensor_id, metric_type, value, unit, recorded_at
    FROM sensor_readings
    WHERE sensor_id = ?
    ORDER BY recorded_at DESC
    LIMIT 100
  `);

  const readings = query.all(sensorId);
  res.json({ sensorId, readings });
});

export default app;
